class Solution:

	def parseBoolExpr(self, expression: str) -> bool:
		if expression == 'f':
			return False
		if expression == 't':
			return True
		if expression[0] == '!':
			return not self.parseBoolExpr(expression[2:-1])
		if expression[0] == '|':
			cursor = 2
			while cursor < len(expression) - 1:
				end_of_next = self.getNextExpr(expression, cursor)
				if self.parseBoolExpr(expression[cursor:end_of_next]):
					return True
				cursor = end_of_next + 1
			return False
		if expression[0] == '&':
			cursor = 2
			while cursor < len(expression) - 1:
				end_of_next = self.getNextExpr(expression, cursor)
				if not self.parseBoolExpr(expression[cursor:end_of_next]):
					return False
				cursor = end_of_next + 1
			return True

	def getNextExpr(self, expression, start):
		if expression[start] == '!' or expression[start] == '|' or expression[start] == '&':
			open_count = 1
			close_count = 0
			start += 1
			while open_count > close_count:
				start += 1
				if expression[start] == '(':
					open_count += 1
				if expression[start] == ')':
					close_count += 1
			return start + 1
		else:
			return start + 1

import os
import sys
from io import BytesIO, IOBase
BUFSIZE = 8192

class FastIO(IOBase):
	newlines = 0

	def __init__(self, file):
		self._fd = file.fileno()
		self.buffer = BytesIO()
		self.writable = 'x' in file.mode or 'r' not in file.mode
		self.write = self.buffer.write if self.writable else None

	def read(self):
		while True:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			if not b:
				break
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines = 0
		return self.buffer.read()

	def readline(self):
		while self.newlines == 0:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			self.newlines = b.count(b'\n') + (not b)
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines -= 1
		return self.buffer.readline()

	def flush(self):
		if self.writable:
			os.write(self._fd, self.buffer.getvalue())
			(self.buffer.truncate(0), self.buffer.seek(0))

class IOWrapper(IOBase):

	def __init__(self, file):
		self.buffer = FastIO(file)
		self.flush = self.buffer.flush
		self.writable = self.buffer.writable
		self.write = lambda s: self.buffer.write(s.encode('ascii'))
		self.read = lambda : self.buffer.read().decode('ascii')
		self.readline = lambda : self.buffer.readline().decode('ascii')
(sys.stdin, sys.stdout) = (IOWrapper(sys.stdin), IOWrapper(sys.stdout))
