def floor_sum(n, m, a, b):
	res = 0
	res += a // m * n * (n - 1) // 2 + b // m * n
	a %= m
	b %= m
	y_max = (a * n + b) // m
	if y_max == 0:
		return res
	x_max = m * y_max - b
	res += (n + -x_max // a) * y_max
	res += floor_sum(y_max, a, m, (x_max + a - 1) // a * a - x_max)
	return res
