def modular_power(a, n, m):
	if n == 0:
		return 1
	a = a % m
	if a < 0:
		a += m
	prod = 1
	pwr = a
	while n != 0:
		if n % 2 != 0:
			prod = prod * pwr % m
		n >>= 1
		if n == 0:
			break
		pwr = pwr * pwr % m
	return prod
MOD_INVERSE_CACHE = {}

def modular_inverse_cached(a, m):
	y = MOD_INVERSE_CACHE.get(m, {}).get(a)
	if y is None:
		y = modular_inverse(a, m)
		if m not in MOD_INVERSE_CACHE:
			MOD_INVERSE_CACHE[m] = {}
		MOD_INVERSE_CACHE[m][a] = y
	return y

def modular_inverse(a, m):
	m0 = m
	y = 0
	x = 1
	if m == 1:
		return 0
	while a > 1:
		q = a // m
		t = m
		m = a % m
		a = t
		t = y
		y = x - q * y
		x = t
	if x < 0:
		x = x + m0
	return x

