class FenwickTree2D:

	def __init__(self, x, y):
		self.size_x = x
		self.size_y = y
		self.data = [[0] * self.size_y for _ in range(self.size_x)]

	def sum(self, x1, y1):
		if min(x1, y1) <= 0:
			return 0
		s = 0
		x = x1
		while x >= 0:
			y = y1
			while y >= 0:
				s += self.data[x][y]
				y = (y & y + 1) - 1
			x = (x & x + 1) - 1
		return s

	def sumrange(self, x1, y1, x2, y2):
		return self.sum(x2, y2) - self.sum(x1 - 1, y2) - self.sum(x2, y1 - 1) + self.sum(x1 - 1, y1 - 1)

	def add(self, x1, y1, w):
		assert min(x1, y1) > 0
		x = x1
		while x < self.size_x:
			y = y1
			while y < self.size_y:
				self.data[x][y] += w
				y |= y + 1
			x |= x + 1
