def value(obj):
	if type(obj) == modint:
		tmp = obj.number
	else:
		tmp = obj
	return tmp % mod

class modint:
	number = 0

	def __init__(self, num):
		self.number = num % mod

	def __add__(self, other):
		tmp = value(other)
		return modint(self.number + tmp)

	def __iadd__(self, other):
		tmp = value(other)
		self.number += tmp
		self.number %= mod
		return self

	def __sub__(self, other):
		tmp = value(other)
		return modint(self.number - tmp)

	def __isub__(self, other):
		tmp = value(other)
		self.number -= tmp
		self.number %= mod
		return self

	def __mul__(self, other):
		tmp = value(other)
		return modint(self.number * tmp)

	def __imul__(self, other):
		tmp = value(other)
		self.number *= tmp
		self.number %= mod
		return self

	def __truediv__(self, other):
		tmp = value(other)
		return self * pow(tmp, mod - 2, mod)

	def __itruediv(self, other):
		tmp = value(other)
		self.number = self / tmp
		self.number %= mod
		return self

	def __repr__(self):
		return str(self.number)

	def __eq__(self, other):
		return value(self) == value(other)

	def __ne__(self, other):
		return value(self) != value(other)

	def __str__(self):
		return str(self.number)

	def __int__(self):
		return self.number

	def __hash__(self):
		return self.number

class polynomial:
