class WeightedUnionFind:

	def __init__(self, n, SUM_UNITY=0):
		self.par = list(range(n))
		self.rank = [0] * n
		self.diff_weight = [SUM_UNITY] * n

	def root(self, x):
		p = self.par[x]
		if p == x:
			return x
		else:
			r = self.root(p)
			self.diff_weight[x] += self.diff_weight[p]
			self.par[x] = r
			return r

	def weight(self, x):
		self.root(x)
		return self.diff_weight[x]

	def same(self, x, y):
		return self.root(x) == self.root(y)

	def unite(self, x, y, w):
		if self.same(x, y):
			return self.diff(x, y) == w
		w += self.weight(x)
		w -= self.weight(y)
		(x, y) = (self.root(x), self.root(y))
		if self.rank[x] < self.rank[y]:
			(x, y) = (y, x)
			w = -w
		if self.rank[x] == self.rank[y]:
			self.rank[x] += 1
		self.par[y] = x
		self.diff_weight[y] = w
		return True

	def diff(self, x, y):
		return self.weight(y) - self.weight(x)

	def get_roots_weights(self):
		roots = []
		weights = []
		for x in range(len(self.par)):
			roots.append(self.root(x))
			weights.append(self.weight(x))
		return (roots, weights)
