		self.cost = co

class MinCostFlow:
	size = 0
	graph = []

	def __init__(self, s):
		self.size = s
		self.graph = [[] for _ in range(s)]

	def add_edge(self, f, t, ca, co):
		self.graph[f].append(Edge(t, f, len(self.graph[t]), ca, co))
		self.graph[t].append(Edge(f, t, len(self.graph[f]) - 1, 0, -co))

	def min_path(self, s, t):
		dist = [inf] * self.size
		route = [None] * self.size
		que = collections.deque()
		inq = [False] * self.size
		dist[s] = 0
		que.append(s)
		inq[s] = True
		while que:
			u = que.popleft()
			inq[u] = False
			for e in self.graph[u]:
				if e.cap == 0:
					continue
				v = e.to
				if dist[v] > dist[u] + e.cost:
					dist[v] = dist[u] + e.cost
					route[v] = e
					if not inq[v]:
						que.append(v)
						inq[v] = True
		if dist[t] == inf:
			return inf
		flow = inf
		v = t
		while v != s:
			e = route[v]
			if flow > e.cap:
				flow = e.cap
			v = e.fron
		c = 0
		v = t
		while v != s:
			e = route[v]
			e.cap -= flow
			self.graph[e.to][e.rev].cap += flow
			c += e.cost * flow
			v = e.fron
		return dist[t]

	def calc_min_cost_flow(self, s, t, flow):
		total_cost = 0
		for i in range(flow):
			c = self.min_path(s, t)
			if c == inf:
				return c
			total_cost += c
		return total_cost

