class Solution:

	def maxDotProduct(self, nums1: List[int], nums2: List[int]) -> int:
		INF = int(1000000000.0)
		(n, m) = (len(nums1), len(nums2))
		DP = [-INF] * (m + 1)
		NDP = [-INF] * (m + 1)
		for a in range(n):
			for b in range(m):
				el = nums1[a] * nums2[b]
				diag = DP[b]
				NDP[b + 1] = max(el, DP[b + 1], NDP[b], diag, diag + el)
			(DP, NDP) = (NDP, DP)
		return DP[-1]

