def powmod(a, x, m):
	y = 1
	while 0 < x:
		if x % 2 == 1:
			y *= a
			y %= m
		x //= 2
		a = a ** 2
		a %= M
	return y
M = 10 ** 9 + 7
prime = Prime()

def solve(s):
	if s == 1:
		return 9
	ans = 0
	n = 1
	c = 9
	while n * c < s:
		n += 1
		c *= 10
	ans += s // n
	for log_r in range(n - 1, n + 1):
		c_r = 9 * 10 ** (log_r - 1)
		sum_r = log_r * c_r
		for log_l in range(1, log_r):
			mid_f = 0
			for i in range(log_l + 1, log_r):
				mid_f += i * 9 * 10 ** (i - 1)
			if s <= mid_f:
				continue
			res = s - mid_f
			c_l = 9 * 10 ** (log_l - 1)
			if log_l * c_l + sum_r < res:
				continue
			g = gcd(log_r, log_l)
			if res % g != 0:
				continue
			c_l_max = min(c_l, (res - 1) // log_l)
			while 0 < c_l_max:
				if (res - log_l * c_l_max) % log_r == 0:
					break
				c_l_max -= 1
			if c_l_max == 0:
				continue
			c_l_min = 1
			if sum_r < res:
				c_l_min = (res - sum_r + log_l - 1) // log_l
			div = log_r // g
			ans += (c_l_max - c_l_min + div) // div
	factors = prime.find_factors(s)
	num_prime_factors = len(factors)
	prime_factors = []
	count_limit = []
	count = [0] * num_prime_factors
	for k in factors.keys():
		prime_factors.append(k)
		count_limit.append(factors[k])
	loop = True
	while loop:
		p = 1
		for (i, f) in enumerate(prime_factors):
			p *= f ** count[i]
		if n <= p:
			ans += 9 * powmod(10, p - 1, M)
			ans += M - s // p
			ans %= M
		count[0] += 1
		for (i, limit) in enumerate(count_limit):
			if limit < count[i]:
				if i == num_prime_factors - 1:
					loop = False
					break
				count[i + 1] += 1
				count[i] = 0
	return ans

