	while i < n:
		j = i + 1
		while j < n:
			if a[j] != a[i]:
				break
			j += 1
		c = j - i
		while c >= len(cnt):
			cnt.append([])
		cnt[c].append(a[i])
		i = j
	best = -1
	for i in range(len(cnt)):
		for u in cnt[i]:
			for j in range(i + 1):
				for v in cnt[j]:
					if u < v:
						if (u, v) not in bad:
							best = max(best, (u + v) * (i + j))
							break
					elif u > v:
						if (v, u) not in bad:
							best = max(best, (u + v) * (i + j))
