def four_piles(n, y):
	(x, r) = divmod(n * y, (y + 1) ** 2)
	return [] if r or x == y else [x + y, x - y, x * y, x // y]

def add_edge(node, adj_lst, s1, s2):
	ind = 0
	max_len = min(len(s1), len(s2))
	while ind < max_len and s1[ind] == s2[ind]:
		ind += 1
	if ind == max_len:
		return max_len < len(s1)
	c1 = ord(s1[ind]) - ord('a')
	c2 = ord(s2[ind]) - ord('a')
	adj_lst[c1].add(c2)
	node.add(c1)
	node.add(c2)
