	for i in range(n - 1):
		(a, b, w) = LI()
		a -= 1
		b -= 1
		v[a].append((b, w))
		v[b].append((a, w))
		f[a] += 1
		f[b] += 1
	bfs = [1] * n
	bfs[s] = 0
	q = deque([s])
	par = [None] * n
	while q:
		x = q.popleft()
		for (y, w) in v[x]:
			if bfs[y]:
				par[y] = [x, w - t * (f[x] - 1)]
				bfs[y] = 0
				q.append(y)
