from bisect import bisect_right

def helper(ele, l1):
	ind = bisect_right(l1, ele)
	if ind == len(l1):
		return abs(l1[ind - 1] - ele)
	elif ind == 0:
		return abs(l1[0] - ele)
	else:
		return min(abs(l1[ind - 1] - ele), abs(l1[ind] - ele))
