class Solution:

	def findMin(self, nums):
		if len(nums) <= 3:
			return min(nums)
		lo = 0
		hi = len(nums) - 1
		mid = (hi + lo) // 2
		if nums[mid] < nums[mid - 1] and nums[mid] < nums[mid + 1]:
			return nums[mid]
		if nums[mid] > nums[lo] and nums[mid] > nums[hi]:
			return self.findMin(nums[mid:])
		else:
			return self.findMin(nums[:mid + 1])

