class Node:
	def __init__(self):
		self.val = 0
		self.idx = 0
		self.add = 0
		self.cover = (0 , 0)
		self.lChild = None
		self.rChild = None
	def __lt__(self , other):
		if (self.idx not in used):
			return True
		if (other.idx not in used):
			return False
		return self.val < other.val
	def __repr__(self):
		return str(self.val)
	def build(self , cover):
		self.cover = cover
		self.idx = cover[0]
		if (cover[0] == cover[1]):
			return
		mid = Mid(cover)
		self.lChild = Node()
		self.rChild = Node()
		self.lChild.build( (cover[0] , mid) )
		self.rChild.build( (mid + 1 , cover[1]) )
	def addDown(self):
		#try
		self.lChild.addValue(self.add)
		self.rChild.addValue(self.add)
		self.add = 0
	def addValue(self , add):
		self.val += add
		self.add += add

	def update(self , cover, add):
		if (cover[0] <= self.cover[0] and cover[1] >= self.cover[1]):
			self.addValue(add)
			return
		if (self.add):
			self.addDown()
		mid = Mid(self.cover)
		if (cover[0] <= mid):
			self.lChild.update(cover , add)
		if (cover[1] > mid):
			self.rChild.update(cover , add)

		ret = max( self.lChild , self.rChild )
		self.val = ret.val
		self.idx = ret.idx

	def query(self , cover):
		if (cover[0] == self.cover[0] and cover[1] == self.cover[1]):
			return self
		if (self.add):
			self.addDown()
		mid = Mid(self.cover)
		if (cover[1] <= mid):
			return self.lChild.query(cover)
		elif (cover[0] > mid):
			return self.rChild.query(cover)
		else:
			vl = self.lChild.query( (cover[0] , mid) )
			vr = self.rChild.query( (mid + 1 , cover[1]) )
			return max(vl , vr)

