class Bit:

	def __init__(self, n):
		self.size = n
		self.tree = [0] * (n + 1)

	def sum(self, i):
		s = 0
		while i > 0:
			s = max(s, self.tree[i])
			i -= i & -i
		return s

	def add(self, i, x):
		while i <= self.size:
			self.tree[i] = max(x, self.tree[i])
			i += i & -i
