def rearranger(k, *args):
	perms = permutations(map(str, args), len(args))
	divisible_by_k = filter(lambda x: int(''.join(x)) % k == 0, perms)
	try:
		rearranged = min(divisible_by_k, key=lambda x: int(''.join(x)))
		return 'Rearrangement: {} generates: {} divisible by {}'.format(', '.join(rearranged), ''.join(rearranged), k)
	except ValueError:
		return 'There is no possible rearrangement'

class Solution:

	def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
		if len(croakOfFrogs) % 5 != 0 or croakOfFrogs[0] != 'c' or croakOfFrogs[-1] != 'k':
			return -1
		letters = {'c': 0, 'r': 0, 'o': 0, 'a': 0, 'k': 0}
		frogs = 0
		temp = 0
		for l in croakOfFrogs:
			letters[l] += 1
			temp = letters['c'] - letters['k']
			if temp > frogs:
				frogs = temp
		c_count = letters['c']
		for letter in letters:
			if letters[letter] != c_count:
				return -1
		return frogs

class Solution:

	def maxDistance(self, grid: List[List[int]]) -> int:
		from collections import deque
		queue = deque()
		for (i, row) in enumerate(grid):
			for (j, cell) in enumerate(row):
				if cell == 1:
					queue.append((i, j, None, None))
		dist = {}
		while queue:
			(i, j, previ, prevj) = queue.popleft()
			if i < 0 or j < 0 or i >= len(grid) or (j >= len(grid[0])):
				continue
			if (i, j) not in dist:
				dist[i, j] = 1 + dist.get((previ, prevj), -1)
				for (di, dj) in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
					(newi, newj) = (i + di, j + dj)
					queue.append((newi, newj, i, j))
		ans = max(list(dist.values()), default=-1)
		return ans if ans != 0 else -1

