		node1.Nodes.append(node2)
		node2.Nodes.append(node1)

	def SetRoot(self, root):
		s = Stack()
		s.push(root)
		while not s.isEmpty():
			node = s.pick()
			if node.Nodes == None:
				s.pop()
				node.Count = len(node.Tag)
				if node.Parent != None:
					node.Parent.Tag = join(node.Parent.Tag, node.Tag)
					node.Tag = None
			else:
				for n in node.Nodes:
					n.Nodes.remove(node)
					n.Parent = node
					s.push(n)
				node.Nodes = None

	def ColorPathFromNode(self, node, color):
