def search(new, lb, ub, a, b):
	while lb <= ub:
		mb = lb + (ub - lb) // 2
		if new[mb][0] <= a and new[mb][0] <= b and (new[mb][1] >= a) and (new[mb][1] >= b):
			return 1
		elif new[mb][0] >= a and new[mb][0] >= b:
			ub = mb - 1
		elif new[mb][1] <= a and new[mb][1] <= b:
			lb = mb + 1
		else:
			return -1
	return -1
