import math

def lcm(F):
	lcmFactors = dict(F[0])
	for f in F[1:]:
		for (n, c) in f.items():
			lcmFactors[n] = max(lcmFactors.get(n, 0), c)
	result = 1
	for (n, c) in lcmFactors.items():
		result *= n ** c
	return result

def factorize(N):
	F = dict()
	while N > 1:
		if N % 2 == 0:
			F[2] = F.get(2, 0) + 1
			N = N // 2
		else:
			for x in range(3, int(math.sqrt(N) + 1), 2):
				if N % x == 0:
					F[x] = F.get(x, 0) + 1
					N = N // x
					break
			else:
				F[N] = F.get(N, 0) + 1
				N = 1
	return F

def f(A, R, F):
	total = 0
	for n in range(1, 2 ** len(A)):
		t = n
		multiplier = -1
		divisor = 1
		factorList = list()
		for i in range(0, len(A)):
			if t & 1:
				factorList.append(F[i])
				multiplier *= -1
			t = t >> 1
			if not t:
				break
		divisor = lcm(factorList)
		common = R // divisor
		total += common * multiplier
	return total

