import sys

def solve():
	inp = sys.stdin.readline
	n = int(inp())
	p = list(map(int, inp().split()))
	q = list(map(int, inp().split()))
	pi = [None] * (n + 1)
	qi = [None] * (n + 1)
	for i in range(n):
		pi[p[i]] = i
		qi[q[i]] = i
	x = pi[1]
	y = qi[1]
	if x > y:
		(x, y) = (y, x)
	res = 0
	if x >= 1:
		res += x * (x + 1) // 2
	if n - 1 - y >= 1:
		res += (n - y - 1) * (n - y) // 2
	if y - x - 1 >= 1:
		res += (y - x - 1) * (y - x) // 2
	l = x
	r = y
	for i in range(2, n):
		x = pi[i]
		y = qi[i]
		if x > y:
			(x, y) = (y, x)
		if not (x >= l and x <= r or (y >= l and y <= r)):
			if y < l:
				u = l - y
			elif x < l:
				u = l - x
			else:
				u = l + 1
			if x > r:
				v = x - r
			elif y > r:
				v = y - r
			else:
				v = n - r
			res += u * v
		l = min(l, x)
		r = max(r, y)
	print(res + 1)

def main():
	solve()
main()

